n = 0; loop (30000, megabuf(n)=0; gmegabuf(n)=0; n +=1; );

MINBPM = 30; MAXBPM = 160; num_res = 30; 
index = 0;
loop (num_res,
  n = index*12;
  BPM      = minbpm * pow(maxbpm/minbpm,index/(num_res-1));
  megabuf(n) = BPM;
  index += 1;
);

pi = 3.1416;
start = rand(5)-5;
ran1  = rand (4) -2;

presetParts.perFrame:
dt = min (1/fps,0.1) ; //Stability !
dec_f = 0.8; dec_m = 1 - 4*dt; dec_s = 1 - 1.25*dt;
start = start * dec_m + (1-dec_m);
vol =  bass+mid+treb; avg = avg*dec_s + vol*(1-dec_s);
excite = atan ((vol-avg))*1.4;

is_beat = above(vol, 1.5*avg + 8*peak) * above (time, tc0+.25);
tc0 = if (is_beat, time,tc0);
trig = is_beat * (beatct%8==0); beatct += is_beat;
peak = if (is_beat,1,peak*dec_m);
bindex += is_beat;
trig = is_beat * (bindex%16==0);
vc = vc*dec_f + (1-dec_f) * excite*0.06;

pu = dec_f*pu + trig*vol/3; pu_ = dec_f*pu_+(1-dec_f)*pu; push=pu_+vc*0;
bindex2 += trig;

if (trig, ran1 = sin(rand (100))*2+0.5, 0);
prog += min(int (bindex/30)-prog,0.1)*dt*20;
prog_ = prog_*dec_m + (1-dec_m) * sin (pi/2*prog) ;
prog2 +=min(0.2, max (-0.2,bindex-prog2))*dt*16;

index=0; maxquad = 0.2;
loop (num_res, n = index*12;  omega=megabuf(n) * 6.2832/60;
  megabuf (n+1) *= 1-0.29*dt; 
  EC_Steps = int (12*omega*dt)+1; //10=ok, aber hier nur wenige res
  loop (EC_Steps, // Euler-Cauchy 
    megabuf (n+1) += (excite - sqr(omega)*megabuf(n+2)) * dt/EC_Steps;
    megabuf (n+2) += megabuf(n+1) * dt/EC_Steps);
  beatcos  = megabuf(n+1);  beatsin = megabuf(n+2)*omega;
  quad     = sqrt (pow(beatsin,2) + pow(beatcos,2)) ;
  if (maxquad < quad,  maxquad = quad, 0);
  megabuf (n+3) = megabuf(n+3) *dec_m +  quad* (1-dec_m);
//  megabuf (n+4) = beatcos * pow(1-index/num_res,1);
  megabuf (n+4) = megabuf (n+4)*dec_s + beatsin * omega*dt* pow(1-index/num_res,1);
  megabuf (n+5) = beatsin * pow(1-index/num_res,1);;
  megabuf (n+8) = gmegabuf (10000+n) ; //size pusher
  index += 1;
);

index = 0; maxind = 0;
loop (num_res,
  n = 12*index;
  if (gmegabuf(n+3) > gmegabuf(maxind+3) ,  maxind = n, 0);
index+=1);
BPM      = minbpm * pow(maxbpm/minbpm,maxind/12/(num_res-1));
ctime += BPM/60*dt*pi;

//Buffer !
size = num_res*12;
delay = min (12, max (3, int (6*40*dt))); delay = 5; wave = 0;
n = 4*delay; loop (4*delay, memcpy (n*size, (n-1)*size, size); n -= 1);

//Pusher Queue
n = num_res;
loop (num_res, 
  gmegabuf (10000+n*12) = gmegabuf(10000+(n-1)*12); //size
  gmegabuf (10001+n*12) = gmegabuf(10001+(n-1)*12); //col
  gmegabuf (10002+n*12) = gmegabuf(10002+(n-1)*12); //smod ?
n-=1;);
gmegabuf (10000) = push; //size
gmegabuf (10001) = bindex2*1.8; //col
//gmegabuf (10002) = min(2,max(-1,8*cos(ctime/16)));
sm = sm*dec_m + (1-dec_m) * ran1;
gmegabuf (10002) = sm;
test = gmegabuf(10002);

n = 0; imax = 0;
loop (num_res,
  t1 += abs(megabuf(n*12+4))*dt/12 * (prog_ + (1-abs(prog_))* min(1,max(-1,2*sin(t1))));
  t2 += abs(megabuf(n*12+5))*dt/6 * (prog_ + (1-abs(prog_))* min(1,max(-1,2*sin(t2))));
n+=1;);

loop (4,
  n = wave * 1000; m = wave * size*delay; k = m + (num_res-1)*12; ring = 0;
  loop (num_res,
  scale =  (megabuf(n+3) +megabuf(k+3))/4; 
  scale = 1;
  gmegabuf(n) = (12-wave) * 0.0019; //Rad
  gmegabuf(n+3) = megabuf(m+3) ;
  smod =  (10+wave* gmegabuf(10002+ring*12))/12 *start ;
  gmegabuf(n+4) = sin((ring+0.5)/num_res*6.28+t1)/3 * smod;
  gmegabuf(n+5) = cos((ring+0.5)/num_res*6.28+t1)/6 * smod;
  gmegabuf(n+4) += atan((megabuf(m+4) - megabuf (k+4))* scale) *0.1;
  gmegabuf(n+5) += atan((megabuf(m+5) + megabuf (k+5))* scale) *0.2;
  gmegabuf(n+7) += megabuf (m+5)*dt*20;
  gmegabuf(n+8)  = megabuf(m+8);
  //Colours
  gmegabuf (n+9)  = 2*pi*ring/num_res + gmegabuf (10001+ring*12);
  gmegabuf (n+10) = 2*pi*ring/num_res+2+ gmegabuf (10001+ring*12) ; 
  gmegabuf (n+11) = 2*pi*ring/num_res+4+ gmegabuf (10001+ring*12) ;
  n+=12; m+=12; k -= 12; ring +=1);
wave +=1);

q1 = 0.34; //mod. col
q2 = 0.35; //mod a - shift
q3 = 1.2; //mod a - scale

//flash2 pos
fsig = max (0,vol-avg*2.2);
ov = if (fsig > ov, fsig, ov*dec_f);
q22 = log (1+ov) * 0.00003; 
if (frame%4==0, r1 = rand(1), 0);
q25 = (r1-0.5)*0.5;

q23 = sin(vol);
q24 = cos(vol);

q12 = t1;
q32 = aspecty;

q14 = cos(ctime);
monitor = q14;
