sampler sampler_rand00;
float cross, noise, z, mask, scale;
float2 rs, rs0, uv1, uv2, uv3, uv4, uvt;
float3 ret1,ret2,struc,flash2;

float3 Get1 (float2 uvi){return GetPixel (uvi);}

shader_body {

float iter = 4+10*saturate (texsize.x/1024*uv.y);
ret = Get1(uv); ret1 = ret; ret2 = ret;
for (int n =1; n < 10; n++) {
  ret1 = max(ret1,Get1(uv+texsize.zw*float2(n,0)));
//  ret2 = max(ret2,Get1(uv+texsize.zw*float2(0,n)));
}
struc = ret1;
mask = saturate(1-16*lum(struc));
struc *= .06/(length(rad/2-length((ret1+ret2*0.2))+0.6));

//BACK
uv4 = (uv-0.5) * (1+0*exp(-pow ((uv.x-0.5)*3-2*q14,2)))+0.5;


noise = (tex2D(sampler_noise_lq,2*uv4).r+0.25);
noise *= 1-tex2D(sampler_noise_lq,2*uv4+texsize.zw*-4).r;
noise *= (0.5+ 0.5*(lum(tex2D(sampler_rand00,uv)) > 0.5))*2;
ret = 0.05+noise*0.5*(1-rad);

ret *= saturate(1-lum(GetBlur2(uv4-0.13))*8);
ret = lerp (ret,struc, !mask);

//NEW FLASH
for (int n = 1; n <= 3; n++)
{
  uvt = tex2D(sampler_noise_lq,n*0.074+q25).xy;
  uv3 = uv4-uvt;
  uv3 = mul (uv3,float2x2 (q23,q24,-q24,q23));
  cross = (0.0001+abs (uv3.x+uv3.y) *abs (uv3.x-uv3.y)) * length(uv3);
  flash2 = (3*q22/cross) *GetBlur1(uvt) * (uvt.x < 0.9)* (uvt.x > 0.1)* (uvt.y < 0.9)* (uvt.y > 0.1);
  flash2 += 100000*mask*q22*saturate(1-2*length (uv3-0.1)) *noise*GetBlur1(uvt);
  ret += flash2;
}
//ret = GetPixel(uv);
//ret *= 1.4;
}
